import{_ as i,l,o as e,c as s,v as t,p as n,x as r,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"MRC 修复","description":"","frontmatter":{"title":"MRC 修复","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mrc-fixup.md","filePath":"litho/mrc-fixup.md","lastUpdated":1789023840000}'),C={name:"litho/mrc-fixup.md"};function c(m,a,E,P,u,_){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="mrc-修复" tabindex="-1">MRC 修复 <a class="header-anchor" href="#mrc-修复" aria-label="Permalink to &quot;MRC 修复&quot;">​</a></h1><div class="epigraph"><p>检查出违例还不是一张可写的版；修复必须把几何拉回掩模厂合同，同时尽量少吐回已经收住的工艺窗。</p><footer>—— 对照掩模厂（mask shop）对 MRC 违例清理与可写性修复的工程通称</footer></div><p><a href="/litho/mask-rule-check">上一课</a>把可写集合写成宽度、间距、面积、jog、尖角。缺口是 OPC/ILT 仍然会撞上这个集合：检查器标红之后，谁来改多边形、怎么改才不把 PV-band 送掉。本课钉 MRC 修复。曲线规则留给 <a href="/litho/curvilinear-mrc">曲线 MRC</a>，本课停在曼哈顿/多边形。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模型循环最小化 EPE，MRC 是硬约束。若只在结束时过滤，一夜之间出现成千上万窄缝、尖刺、过短 jog、面积过小的 SRAF。手工修全芯片不可能。必须有自动修复：合并碎片、拉宽/拉缝、删或并助条、倒角、清除针尖。每一步都在改掩模频谱，上一课的窗口可能吐回去。</p><p>掩模厂的合同是写入、蚀刻、检测都能过，不是「光学上看着能印」。修复若只图检查器变绿，AEI 热区会回来。问题是带约束的投影，不是美工。</p><h3 id="修复优先级不是随便的" tabindex="-1">修复优先级不是随便的 <a class="header-anchor" href="#修复优先级不是随便的" aria-label="Permalink to &quot;修复优先级不是随便的&quot;">​</a></h3><p>主图形宽度/间距违例优先于助条：主图形关系到电学连通。SRAF 过密往往直接删或外移。尖角和微 jog 多半是碎片过碎的伪影，合并比继续迭代更稳。面积过小的孔或衬线可能是真的光学需要，删了要再跑局部 OPC，不能只删。</p><p><span class="marginnote">MRC 绿了不等于 mask shop 收下。写入机的剂量图、吸收体蚀刻还有自己的热点。修复输出仍要过一次制造规则，而不是只过设计侧检查器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型流水：OPC/ILT → MRC → 分类违例 → 规则或模型修复 → 局部再 OPC → 再 MRC，直到清零或人工热区。规则修复快：最小宽度往外推、最小间距往里挤、短 jog 拉直。模型修复在违例邻域重跑带 MRC 惩罚的 OPC，保留窗口。</p><p>与其事后修，不如迭代内投影：每步移动后夹紧到合法集合。PW-OPC 的工艺点代价加上 MRC 惩罚，比先炸后修更少振荡。计算预算在热区用模型修，规则区用几何夹紧。</p><h3 id="掩模厂回环" tabindex="-1">掩模厂回环 <a class="header-anchor" href="#掩模厂回环" aria-label="Permalink to &quot;掩模厂回环&quot;">​</a></h3><p>有些违例只有写出版、量了 CD 才知道（蚀刻偏置、写入模糊）。shop 回注到 OPC 团队，修复规则升级。这是日历项，不是软件按钮。曲线写入会把违例语言改成曲率，但「先投影再签核」的结构不变。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>几何夹紧改变的是高频：尖刺、窄缝对应掩模频谱的高频，透镜本会滤掉一部分，所以有时夹紧对空中像伤害不大——这是修复能成立的物理理由。但 SRAF 宽度刚好卡在打印阈值上时，夹紧会让助条在角点印出或失效，PV-band 先坏。因此修复后必须在原工艺点上重评带，而不是只跑 MRC。</p><p>碎片过短是违例工厂：优化爱用短碎片贴拐角，MRC 恨短 jog。修复合并碎片，等于回到更粗的自由度，窗口可能略放，但可写。这是和 ILT 正则化同一方向的投影。</p><p><span class="marginnote">不要把「fixup 脚本」当成第二套 OPC。它没有独立的物理模型，只有合法集合。签核仍是成像 + 胶 + 刻蚀。</span></p>',18)),(e(),n(d,null,{default:r(()=>[h(o,{id:"mermaid-52",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPC%5B%22OPC%20%2F%20ILT%20%E8%BE%93%E5%87%BA%22%5D%20--%3E%20CHK%5B%22MRC%22%5D%0A%20%20CHK%20--%3E%20OK%5B%22%E5%8F%AF%E5%86%99%E5%A4%9A%E8%BE%B9%E5%BD%A2%22%5D%0A%20%20CHK%20--%3E%20VIOL%5B%22%E8%BF%9D%E4%BE%8B%E5%88%86%E7%B1%BB%22%5D%0A%20%20VIOL%20--%3E%20RULE%5B%22%E5%87%A0%E4%BD%95%E5%A4%B9%E7%B4%A7%20%2F%20%E5%88%A0%20SRAF%22%5D%0A%20%20VIOL%20--%3E%20REOPC%5B%22%E9%82%BB%E5%9F%9F%E5%86%8D%20OPC%22%5D%0A%20%20RULE%20--%3E%20CHK%0A%20%20REOPC%20--%3E%20CHK%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多束机的炮表，也不把曲线曲率规则提前展开。不要发明某 mask shop 的内部规则编号。后课默认：说到 TAPOUT，OPC 收敛与 MRC 清零是同一里程碑的两半。</p><p>随机缺陷、空白版坑不是 MRC 能修的。</p><p><span class="marginnote">修复日志要进变更：哪类违例用规则、哪类强制再 OPC。否则窗口回退无法追溯。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MRC 违例必须自动拉回可写集合，不能靠全芯片手修。</li><li>夹紧改高频；对 SRAF 可能伤 PV-band，修后要重评工艺点。</li><li>主图形优先于助条；短 jog 宜合并碎片。</li><li>迭代内投影比结束时一次性修更稳。</li><li>出处：掩模厂 MRC 与可写性修复的工程通称。</li></ul>',6))])}const f=i(C,[["render",c]]);export{A as __pageData,f as default};
